#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [EntityBehaviourDefinition(VanillaEnemyNames.skelebomb)]
    public class Skelebomb : AIEntityBehaviour
    {
        public Skelebomb(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetStateTimer(entity, new FrameTimer(CAST_COOLDOWN));
            SetExplode(entity, true);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetModelProperty("NotHoldingBomb", !GetExplode(entity));
            var stateTimer = GetStateTimer(entity);
            if (!GetExplode(entity))
                return;
            if (entity.State == STATE_SPECIAL_MOVE)
            {
                if (stateTimer.RunToExpiredOrNull())
                {
                    EndCasting(entity);
                    SetExplode(entity, false);
                    Explode(entity, entity.GetDamage() * 3, entity.GetFaction());
                    entity.Die(new DamageEffectList(VanillaDamageEffects.SELF_DAMAGE), entity);
                    entity.Level.ShakeScreen(5, 0, 20);
                }
            }
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (entity.IsDead)
                return;
            if (entity.State == VanillaEnemyStates.MELEE_ATTACK && GetExplode(entity))
            {
                if (entity.RNG.Next(200) == 0)
                {
                    StartCasting(entity);
                }
            }
        }
        public override void PostTakeDamage(DamageOutput output)
        {
            base.PostTakeDamage(output);
            if (output.BodyResult == null)
                return;
            var self = output.Entity;
            if (output.BodyResult.HasEffect(VanillaDamageEffects.IMPACT))
            {
                if (GetExplode(self))
                {
                    self.AddBuff<SkelebombPunchedBuff>();
                    if (self.State != STATE_SPECIAL_MOVE)
                        StartCasting(self);
                }
            }
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (info.Effects.HasEffect(VanillaDamageEffects.NO_DEATH_TRIGGER))
                return;
            if (!GetExplode(entity))
                return;
            if (entity.IsPerformingSpecialMove())
            {
                EndCasting(entity);
                SetExplode(entity, false);
                Explode(entity, entity.GetDamage() * 3, entity.GetFaction());
                entity.Level.ShakeScreen(5, 0, 20);
            }
            else
            {
                var offset = BOMB_OFFSET;
                offset.x *= entity.GetFacingX();
                entity.SpawnWithParams(VanillaEnemyID.bomb, entity.Position + offset)?.Let(e =>
                {
                    e.Velocity = entity.Velocity;
                });
                SetExplode(entity, false);
            }
        }
        public static void SetStateTimer(Entity entity, FrameTimer timer)
        {
            entity.SetBehaviourField(ID, PROP_STATE_TIMER, timer);
        }
        public static FrameTimer? GetStateTimer(Entity entity)
        {
            return entity.GetBehaviourField<FrameTimer>(ID, PROP_STATE_TIMER);
        }
        public static void SetExplode(Entity entity, bool timer)
        {
            entity.SetBehaviourField(ID, PROP_HAS_BOMB, timer);
        }
        public static bool GetExplode(Entity entity)
        {
            return entity.GetBehaviourField<bool>(ID, PROP_HAS_BOMB);
        }

        public static void StartCasting(Entity entity)
        {
            entity.SetPerformingSpecialMove(true);
            entity.PlaySound(VanillaSoundID.fuse);
            var stateTimer = GetStateTimer(entity);
            stateTimer?.ResetTime(CAST_TIME);
        }
        private void EndCasting(Entity entity)
        {
            entity.SetPerformingSpecialMove(false);
            var stateTimer = GetStateTimer(entity);
            stateTimer?.ResetTime(CAST_COOLDOWN);
        }
        public static void Explode(Entity entity, float damage, int faction)
        {
            var scale = entity.GetFinalScale();
            var scaleX = Mathf.Abs(scale.x);
            var range = entity.GetRange() * scaleX;

            DamageEffectList damageEffectList = new DamageEffectList(VanillaDamageEffects.EXPLOSION, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.MUTE);
            if (entity.HasBuff<SkelebombPunchedBuff>())
            {
                entity.ExplodeAgainstFriendly(entity.GetCenter(), range, faction, damage, damageEffectList);
            }
            else
            {
                entity.Explode(entity.GetCenter(), range, faction, damage, damageEffectList);
            }

            Explosion.Spawn(entity, entity.GetCenter(), range);
            entity.PlaySound(VanillaSoundID.explosion, scaleX == 0 ? 1000 : 1 / (scaleX));
        }

        #region ����
        private const int CAST_COOLDOWN = 300;
        private const int CAST_TIME = 30;
        private const int STATE_SPECIAL_MOVE = VanillaEnemyStates.SPECIAL_MOVE;
        private Vector3 BOMB_OFFSET = new Vector3(32, 40, 0);
        public static readonly NamespaceID ID = VanillaEnemyID.skelebomb;
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("StateTimer");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_CASTING = new VanillaEntityPropertyMeta<bool>("Casting");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_HAS_BOMB = new VanillaEntityPropertyMeta<bool>("hasBomb");
        #endregion ����
    }
}
